// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address x, address y) public {
        // step 1: admin transfers ownership to an arbitrary fuzzed address x
        vm.prank(address(this));
        c.setOwner(x);

        // step 2: admin must STILL be able to set owner (admin is the fixed deployer,
        // not the mutable owner). In the mutant, the guard checks msg.sender == owner,
        // so after owner moved away from admin, admin's call reverts.
        vm.prank(address(this));
        bool ok;
        try c.setOwner(y) { ok = true; } catch { ok = false; }

        assertTrue(ok && c.owner() == y);
    }
}
